pm.test("The Answer contains The List 'Categories'", function () {
    pm.expect(pm.response.json()).to.have.property("categories");
});

pm.test("Each Category must have a ‘Name’ and cannot be Empty", function () {
    const categorias = pm.response.json().categories;

    pm.expect(categorias).to.be.an("array");
    pm.expect(categorias.length).to.be.greaterThan(0);

    categorias.forEach(function (categoria, index) {
        pm.expect(categoria, `Index of Category ${index}`).to.have.property("name");

        pm.expect(categoria.name, `Name of Category at Index ${index}`)
            .to.be.a("string");

        pm.expect(categoria.name.trim().length, `Name cannot be Empty Check ${index}`)
            .to.be.greaterThan(0);
    });
});

